<?php $pageTitle='Jobs'; require 'config.php'; require 'includes/functions.php'; require_role('recruiter');$uid=user()['id'];$role=user()['role'];
if($_SERVER['REQUEST_METHOD']==='POST' && $role==='recruiter'){ $stmt=$pdo->prepare('INSERT INTO jobs(recruiter_id,title,company_name,description,responsibilities,requirements,required_skills,experience_required,location,salary,duration,deadline,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$uid,trim($_POST['title']),trim($_POST['company_name']),trim($_POST['description']),trim($_POST['responsibilities']),trim($_POST['requirements']),trim($_POST['required_skills']),trim($_POST['experience_required']),trim($_POST['location']),trim($_POST['salary']),trim($_POST['duration']),($_POST['deadline']??'')?:null,'open']);flash('success','Job published.');header('Location: jobs.php');exit;}
if(isset($_GET['apply']) && $role==='student'){ $jid=(int)$_GET['apply'];$stmt=$pdo->prepare('INSERT IGNORE INTO applications(job_id,student_id,status) VALUES(?,?,?)');$stmt->execute([$jid,$uid,'interested']);flash('success','Interest sent to recruiter.');header('Location: jobs.php');exit;}
$jobs=$pdo->query("SELECT j.*,u.name recruiter_name FROM jobs j JOIN users u ON u.id=j.recruiter_id WHERE j.status='open' ORDER BY j.created_at DESC")->fetchAll();include 'includes/header.php';?>
<?php if($role==='recruiter'):?><div class="card"><h2>Create Job Listing</h2><form method="post"><div class="grid two"><div class="form-group"><label>Job Title</label><input name="title" required></div><div class="form-group"><label>Company</label><input name="company_name" required></div></div><div class="form-group"><label>Description</label><textarea name="description" required></textarea></div><div class="grid two"><div class="form-group"><label>Responsibilities</label><textarea name="responsibilities"></textarea></div><div class="form-group"><label>Requirements</label><textarea name="requirements"></textarea></div></div><div class="grid two"><div class="form-group"><label>Required Skills</label><input name="required_skills"></div><div class="form-group"><label>Experience</label><input name="experience_required"></div><div class="form-group"><label>Location</label><input name="location"></div><div class="form-group"><label>Salary</label><input name="salary"></div><div class="form-group"><label>Duration</label><input name="duration"></div><div class="form-group"><label>Deadline</label><input type="date" name="deadline"></div></div><button class="btn">Publish Listing</button></form></div><?php endif; ?>
<h2 class="section-title">Open Opportunities</h2><div class="grid"><?php foreach($jobs as $j):?><div class="card"><span class="badge"><?=e($j['location']?:'Flexible')?></span><h3><?=e($j['title'])?></h3><p class="muted"><?=e($j['company_name'])?> • <?=e($j['salary']?:'Compensation not listed')?></p><p><?=e($j['description'])?></p><p><b>Skills:</b> <?=e($j['required_skills']?:'Not specified')?></p><?php if($role==='student'):?><a class="btn" href="jobs.php?apply=<?=$j['id']?>">Interested</a><?php endif;?></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
